1: //! TopoGrafix GPX 1.1 trackpoint exporter.
2: //!
3: //! Generates standard GPX 1.1 XML with `<ele>` MSL orthometric elevation,
4: //! strict ISO 8601 UTC `<time>` with trailing 'Z', standard kinematic tags (`<speed>`, `<course>`, `<sat>`),
5: //! landmark waypoints (`<wpt>`), and rich drone sensor telemetry extensions (`<extensions><uav:telemetry>`).
6: 
7: use std::io::Write;
8: use chrono::DateTime;
9: 
10: use crate::error::ExportError;
11: use crate::exporters::FlightExporter;
12: use crate::model::FlightDataset;
13: 
14: /// Configuration options for the GPX exporter.
15: #[derive(Debug, Clone)]
16: pub struct GpxOptions {
17:     /// Whether to emit UAV sensor extension tags (`<extensions><uav:telemetry>`).
18:     pub include_extensions: bool,
19:     /// Whether to emit landmark waypoints (`<wpt>`) before the track.
20:     pub include_waypoints: bool,
21:     /// Time discontinuity threshold in seconds to trigger segment split (e.g. 5.0s).
22:     pub segment_gap_threshold_s: f64,
23: }
24: 
25: impl Default for GpxOptions {
26:     fn default() -> Self {
27:         Self {
28:             include_extensions: true,
29:             include_waypoints: true,
30:             segment_gap_threshold_s: 5.0,
31:         }
32:     }
33: }
34: 
35: /// TopoGrafix GPX 1.1 flight exporter.
36: #[derive(Debug, Clone, Default)]
37: pub struct GpxExporter {
38:     options: GpxOptions,
39: }
40: 
41: impl GpxExporter {
42:     /// Constructs a new `GpxExporter` with specified options.
43:     pub fn new(options: GpxOptions) -> Self {
44:         Self { options }
45:     }
46: 
47:     fn format_iso8601_utc(ms: i64) -> String {
48:         DateTime::from_timestamp_millis(ms)
49:             .map(|dt| dt.to_rfc3339_opts(chrono::SecondsFormat::Millis, true))
50:             .unwrap_or_else(|| "1970-01-01T00:00:00.000Z".to_string())
51:     }
52: 
53:     fn escape_xml(s: &str) -> String {
54:         s.replace('&', "&amp;")
55:             .replace('<', "&lt;")
56:             .replace('>', "&gt;")
57:             .replace('"', "&quot;")
58:             .replace('\'', "&apos;")
59:     }
60: }
61: 
62: impl FlightExporter for GpxExporter {
63:     fn export<W: Write>(&self, dataset: &FlightDataset, writer: &mut W) -> Result<(), ExportError> {
64:         writer.write_all(b"<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<gpx version=\"1.1\" creator=\"OpenFlightReader\"\n     xmlns=\"http://www.topografix.com/GPX/1/1\"\n     xmlns:xsi=\"http://www.w3.org/2001/XMLSchema-instance\"\n     xmlns:uav=\"https://openflightreader.org/schema/gpx/1.0\"\n     xsi:schemaLocation=\"http://www.topografix.com/GPX/1/1 http://www.topografix.com/GPX/1/1/gpx.xsd\">\n")?;
65: 
66:         // 1. Waypoints MUST precede <trk> in GPX 1.1 XSD schema
67:         if self.options.include_waypoints && !dataset.points.is_empty() {
68:             // Takeoff Point Waypoint
69:             let first_pt = dataset
70:                 .points
71:                 .iter()
72:                 .find(|p| p.is_motor_on)
73:                 .unwrap_or(&dataset.points[0]);
74: 
75:             write!(
76:                 writer,
77:                 "  <wpt lat=\"{:.8}\" lon=\"{:.8}\">\n    <ele>{:.2}</ele>\n    <time>{}</time>\n    <name>Takeoff Point</name>\n    <sym>Airport</sym>\n  </wpt>\n",
78:                 first_pt.latitude,
79:                 first_pt.longitude,
80:                 first_pt.altitude_msl,
81:                 Self::format_iso8601_utc(first_pt.timestamp_utc_ms)
82:             )?;
83: 
84:             // Home Point Waypoint
85:             if let (Some(h_lat), Some(h_lon), Some(h_alt)) = (
86:                 dataset.metadata.home_latitude,
87:                 dataset.metadata.home_longitude,
88:                 dataset.metadata.home_altitude_msl,
89:             ) {
90:                 write!(
91:                     writer,
92:                     "  <wpt lat=\"{:.8}\" lon=\"{:.8}\">\n    <ele>{:.2}</ele>\n    <name>Home Point</name>\n    <sym>Home</sym>\n  </wpt>\n",
93:                     h_lat, h_lon, h_alt
94:                 )?;
95:             }
96:         }
97: 
98:         let trk_name = dataset
99:             .metadata
100:             .aircraft_model
101:             .as_deref()
102:             .unwrap_or("DJI Flight Track");
103: 
104:         write!(
105:             writer,
106:             "  <trk>\n    <name>{}</name>\n",
107:             Self::escape_xml(trk_name)
108:         )?;
109: 
110:         if dataset.points.is_empty() {
111:             writer.write_all(b"    <trkseg></trkseg>\n  </trk>\n</gpx>\n")?;
112:             return Ok(());
113:         }
114: 
115:         // Partition points into continuous track segments on time gaps (> threshold)
116:         let mut segments: Vec<&[crate::model::TelemetryPoint]> = Vec::new();
117:         let mut seg_start = 0;
118: 
119:         for i in 1..dataset.points.len() {
120:             let dt = dataset.points[i].elapsed_s - dataset.points[i - 1].elapsed_s;
121:             if dt > self.options.segment_gap_threshold_s {
122:                 segments.push(&dataset.points[seg_start..i]);
123:                 seg_start = i;
124:             }
125:         }
126:         segments.push(&dataset.points[seg_start..]);
127: 
128:         let home_lat = dataset.metadata.home_latitude.unwrap_or(0.0);
129:         let home_lon = dataset.metadata.home_longitude.unwrap_or(0.0);
130: 
131:         for seg in segments {
132:             writer.write_all(b"    <trkseg>\n")?;
133: 
134:             for pt in seg {
135:                 let time_str = Self::format_iso8601_utc(pt.timestamp_utc_ms);
136:                 let heading = if pt.yaw_deg < 0.0 {
137:                     pt.yaw_deg + 360.0
138:                 } else {
139:                     pt.yaw_deg
140:                 };
141: 
142:                 // Standard GPX 1.1 elements: ele, time, speed, course, sat
143:                 write!(
144:                     writer,
145:                     "      <trkpt lat=\"{:.8}\" lon=\"{:.8}\">\n        <ele>{:.2}</ele>\n        <time>{}</time>\n        <speed>{:.2}</speed>\n        <course>{:.1}</course>\n        <sat>{}</sat>\n",
146:                     pt.latitude,
147:                     pt.longitude,
148:                     pt.altitude_msl,
149:                     time_str,
150:                     pt.ground_speed_mps,
151:                     heading,
152:                     pt.gps_satellites
153:                 )?;
154: 
155:                 // UAS Telemetry Extensions
156:                 if self.options.include_extensions {
157:                     let home_dist = if home_lat != 0.0 || home_lon != 0.0 {
158:                         flightreader_core::geo::geodesic_distance(
159:                             pt.latitude,
160:                             pt.longitude,
161:                             home_lat,
162:                             home_lon,
163:                         )
164:                     } else {
165:                         0.0
166:                     };
167: 
168:                     write!(
169:                         writer,
170:                         "        <extensions>\n          <uav:telemetry>\n            <uav:heightAgl>{:.2}</uav:heightAgl>\n            <uav:verticalSpeed>{:.2}</uav:verticalSpeed>\n            <uav:pitch>{:.1}</uav:pitch>\n            <uav:roll>{:.1}</uav:roll>\n            <uav:yaw>{:.1}</uav:yaw>\n            <uav:batteryPercent>{}</uav:batteryPercent>\n            <uav:batteryVoltage>{:.3}</uav:batteryVoltage>\n            <uav:flightMode>{}</uav:flightMode>\n            <uav:rcThrottle>{}</uav:rcThrottle>\n            <uav:rcElevator>{}</uav:rcElevator>\n            <uav:rcAileron>{}</uav:rcAileron>\n            <uav:rcRudder>{}</uav:rcRudder>\n            <uav:homeDistance>{:.2}</uav:homeDistance>\n          </uav:telemetry>\n        </extensions>\n",
171:                         pt.altitude_agl,
172:                         pt.climb_rate_mps,
173:                         pt.pitch_deg,
174:                         pt.roll_deg,
175:                         pt.yaw_deg,
176:                         pt.battery_pct,
177:                         pt.battery_voltage_mv as f64 / 1000.0,
178:                         Self::escape_xml(&pt.flight_mode),
179:                         (pt.rc_throttle * 100.0).round() as i8,
180:                         (pt.rc_elevator * 100.0).round() as i8,
181:                         (pt.rc_aileron * 100.0).round() as i8,
182:                         (pt.rc_rudder * 100.0).round() as i8,
183:                         home_dist
184:                     )?;
185:                 }
186: 
187:                 writer.write_all(b"      </trkpt>\n")?;
188:             }
189: 
190:             writer.write_all(b"    </trkseg>\n")?;
191:         }
192: 
193:         writer.write_all(b"  </trk>\n</gpx>\n")?;
194:         Ok(())
195:     }
196: }
